-- ============================================================================
-- Harbourstone Financial Group - HR - Redshift
-- HR data for Harbourstone Financial Group: employees, salaries, payroll,
-- leave, performance reviews and emergency contacts. Every company's HR data
-- has the same structure, in its own schema of the hr database.
-- Generated by data/generator (make data). Run the whole file top to bottom;
-- it can be re-run and replaces the tables each time.
-- Dates are relative to the day the script runs, so 'today' and 'this month'
-- always have data. All people, companies and identifiers are fictional.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Setup
-- Create the database once and connect to it before running this script:
--   CREATE DATABASE hr;
-- Redshift has no CREATE OR REPLACE TABLE, so tables are dropped and
-- recreated.
-- ----------------------------------------------------------------------------

CREATE SCHEMA IF NOT EXISTS harbourstone;

SET search_path TO harbourstone;

-- ============================================================================
-- Harbourstone Financial Group HR (harbourstone)
-- HR data for Harbourstone Financial Group from its HR and payroll systems.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Bronze: raw extracts from the source systems, loaded as-is.
-- ----------------------------------------------------------------------------

-- bronze_departments: Departments and business units from the HR system
-- (HRIS).
--   Rows: 12

DROP TABLE IF EXISTS harbourstone.bronze_departments;

CREATE TABLE harbourstone.bronze_departments (
  department_id VARCHAR(256),
  department_name VARCHAR(256),
  business_unit VARCHAR(256),
  cost_centre VARCHAR(256),
  head_employee_id VARCHAR(256),
  _source_system VARCHAR(256),
  _batch_id VARCHAR(256)
);


-- bronze_employees: Employee master records from the HR system (HRIS). Raw
-- values: gender and country spellings vary.
--   Columns of note:
--     first_name: Person name
--     last_name: Person name
--     date_of_birth: PII: date of birth
--     gender: Sensitive: gender
--     personal_email: PII: personal email
--     mobile_phone: PII: phone number
--     home_address: PII: home address
--     tax_id: Highly sensitive: national tax ID (TFN, IRD, NRIC or NI
--       number)
--     bank_bsb: Financial: salary account BSB
--     bank_account_number: Financial: salary account number
--     termination_reason: Sensitive: reason for leaving
--   Rows: 240

DROP TABLE IF EXISTS harbourstone.bronze_employees;

CREATE TABLE harbourstone.bronze_employees (
  employee_id VARCHAR(256),
  first_name VARCHAR(256),
  last_name VARCHAR(256),
  preferred_name VARCHAR(256),
  date_of_birth DATE,
  gender VARCHAR(256),
  personal_email VARCHAR(256),
  work_email VARCHAR(256),
  mobile_phone VARCHAR(256),
  home_address VARCHAR(256),
  suburb VARCHAR(256),
  state VARCHAR(256),
  postcode VARCHAR(256),
  country VARCHAR(256),
  tax_id VARCHAR(256),
  tax_id_type VARCHAR(256),
  bank_bsb VARCHAR(256),
  bank_account_number VARCHAR(256),
  department_id VARCHAR(256),
  position_title VARCHAR(256),
  manager_id VARCHAR(256),
  employment_type VARCHAR(256),
  hire_date DATE,
  termination_date DATE,
  termination_reason VARCHAR(256),
  work_location VARCHAR(256),
  _source_system VARCHAR(256),
  _batch_id VARCHAR(256)
);


-- bronze_compensation: Salary history from the HR system: one row per change.
--   Columns of note:
--     base_salary: Sensitive: salary, in local currency
--   Rows: 321

DROP TABLE IF EXISTS harbourstone.bronze_compensation;

CREATE TABLE harbourstone.bronze_compensation (
  comp_id VARCHAR(256),
  employee_id VARCHAR(256),
  effective_date DATE,
  base_salary DECIMAL(12,2),
  currency VARCHAR(256),
  bonus_target_pct DECIMAL(5,1),
  super_rate_pct DECIMAL(5,1),
  pay_grade VARCHAR(256),
  change_reason VARCHAR(256),
  _source_system VARCHAR(256),
  _batch_id VARCHAR(256)
);


-- bronze_payroll: Payslips for the last four fortnightly pay runs, from the
-- payroll system.
--   Columns of note:
--     gross_pay: Sensitive: pay
--     net_pay: Sensitive: pay
--   Rows: 856

DROP TABLE IF EXISTS harbourstone.bronze_payroll;

CREATE TABLE harbourstone.bronze_payroll (
  payslip_id VARCHAR(256),
  employee_id VARCHAR(256),
  pay_period_end DATE,
  gross_pay DECIMAL(12,2),
  tax_withheld DECIMAL(12,2),
  super_contribution DECIMAL(12,2),
  net_pay DECIMAL(12,2),
  currency VARCHAR(256),
  _source_system VARCHAR(256),
  _batch_id VARCHAR(256)
);


-- bronze_leave_requests: Leave requests from the HR system, past and upcoming.
--   Columns of note:
--     reason: Free text: may contain health information
--   Rows: 384

DROP TABLE IF EXISTS harbourstone.bronze_leave_requests;

CREATE TABLE harbourstone.bronze_leave_requests (
  leave_id VARCHAR(256),
  employee_id VARCHAR(256),
  leave_type VARCHAR(256),
  start_date DATE,
  end_date DATE,
  days_taken DECIMAL(5,1),
  leave_status VARCHAR(256),
  reason VARCHAR(4096),
  _source_system VARCHAR(256),
  _batch_id VARCHAR(256)
);


-- bronze_performance_reviews: Annual performance reviews written by managers.
--   Columns of note:
--     rating: 1 (did not meet) to 5 (outstanding)
--     review_text: Free text: performance and sometimes health details
--   Rows: 232

DROP TABLE IF EXISTS harbourstone.bronze_performance_reviews;

CREATE TABLE harbourstone.bronze_performance_reviews (
  review_id VARCHAR(256),
  employee_id VARCHAR(256),
  reviewer_id VARCHAR(256),
  review_period VARCHAR(256),
  rating INT,
  review_text VARCHAR(4096),
  _source_system VARCHAR(256),
  _batch_id VARCHAR(256)
);


-- bronze_emergency_contacts: Next of kin and emergency contacts.
--   Columns of note:
--     contact_name: Person name
--     phone: PII: phone number
--   Rows: 240

DROP TABLE IF EXISTS harbourstone.bronze_emergency_contacts;

CREATE TABLE harbourstone.bronze_emergency_contacts (
  contact_id VARCHAR(256),
  employee_id VARCHAR(256),
  contact_name VARCHAR(256),
  relationship VARCHAR(256),
  phone VARCHAR(256),
  _source_system VARCHAR(256),
  _batch_id VARCHAR(256)
);


-- ----------------------------------------------------------------------------
-- Silver: cleaned, typed and conformed. Built from bronze.
-- ----------------------------------------------------------------------------

-- silver_employees: Cleaned employees with department, age, tenure, active
-- flag and region.

DROP TABLE IF EXISTS harbourstone.silver_employees;

CREATE TABLE harbourstone.silver_employees
AS
WITH base AS (
  SELECT
    e.employee_id,
    INITCAP(TRIM(e.first_name)) AS first_name,
    INITCAP(TRIM(e.last_name)) AS last_name,
    COALESCE(e.preferred_name, e.first_name) AS preferred_name,
    e.date_of_birth,
    CAST(FLOOR(DATEDIFF(day, CAST(e.date_of_birth AS DATE), CAST(CURRENT_DATE AS DATE)) / 365.25) AS INT) AS age,
    CASE UPPER(LEFT(TRIM(e.gender), 1)) WHEN 'F' THEN 'Female' WHEN 'M' THEN 'Male' ELSE 'Non-binary' END AS gender,
    LOWER(TRIM(e.personal_email)) AS personal_email,
    e.work_email,
    e.mobile_phone,
    e.home_address,
    e.suburb,
    e.state,
    e.postcode,
    CASE WHEN UPPER(TRIM(e.country)) IN ('AU', 'AUS', 'AUSTRALIA') THEN 'AU' WHEN UPPER(TRIM(e.country)) IN ('NZ', 'NZL', 'NEW ZEALAND') THEN 'NZ' WHEN UPPER(TRIM(e.country)) IN ('SG', 'SGP', 'SINGAPORE') THEN 'SG' WHEN UPPER(TRIM(e.country)) IN ('GB', 'GBR', 'UK', 'UNITED KINGDOM') THEN 'GB' WHEN UPPER(TRIM(e.country)) IN ('US', 'USA', 'UNITED STATES') THEN 'US' ELSE UPPER(TRIM(e.country)) END AS country,
    REGEXP_REPLACE(e.tax_id, '[^0-9A-Za-z]', '') AS tax_id,
    e.tax_id_type,
    e.bank_bsb,
    e.bank_account_number,
    e.department_id,
    d.department_name,
    d.business_unit,
    e.position_title,
    e.manager_id,
    e.employment_type,
    e.hire_date,
    e.termination_date,
    e.termination_reason,
    e.work_location,
    CASE WHEN e.termination_date IS NULL THEN TRUE ELSE FALSE END AS is_active,
    ROUND(DATEDIFF(day, CAST(e.hire_date AS DATE), CAST(COALESCE(e.termination_date, CURRENT_DATE) AS DATE)) / 365.25, 1) AS tenure_years
  FROM harbourstone.bronze_employees e
  LEFT JOIN harbourstone.bronze_departments d ON d.department_id = e.department_id
)
SELECT base.*, CASE WHEN base.country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN base.country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN base.country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM base;

-- silver_compensation: Salary history with AUD equivalent; is_current marks
-- each employee's current salary.

DROP TABLE IF EXISTS harbourstone.silver_compensation;

CREATE TABLE harbourstone.silver_compensation
AS
WITH ranked AS (
  SELECT c.*, ROW_NUMBER() OVER (PARTITION BY c.employee_id ORDER BY c.effective_date DESC) AS rn
  FROM harbourstone.bronze_compensation c
)
SELECT
  c.comp_id,
  c.employee_id,
  c.effective_date,
  CAST(c.base_salary AS DECIMAL(18,2)) AS base_salary,
  c.currency,
  CAST(c.base_salary * CASE c.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS DECIMAL(18,2)) AS base_salary_aud,
  c.bonus_target_pct,
  c.super_rate_pct,
  c.pay_grade,
  c.change_reason,
  CASE WHEN c.rn = 1 THEN TRUE ELSE FALSE END AS is_current,
  e.department_name,
  e.business_unit,
  e.gender,
  e.is_active,
  e.country,
  e.region
FROM ranked c
JOIN harbourstone.silver_employees e ON e.employee_id = c.employee_id;

-- silver_payroll: Payslips with department, region and AUD equivalent.

DROP TABLE IF EXISTS harbourstone.silver_payroll;

CREATE TABLE harbourstone.silver_payroll
AS
SELECT
  p.payslip_id,
  p.employee_id,
  p.pay_period_end,
  CAST(p.gross_pay AS DECIMAL(18,2)) AS gross_pay,
  CAST(p.tax_withheld AS DECIMAL(18,2)) AS tax_withheld,
  CAST(p.super_contribution AS DECIMAL(18,2)) AS super_contribution,
  CAST(p.net_pay AS DECIMAL(18,2)) AS net_pay,
  p.currency,
  CAST(p.gross_pay * CASE p.currency WHEN 'AUD' THEN 1.00 WHEN 'NZD' THEN 0.92 WHEN 'SGD' THEN 1.13 WHEN 'GBP' THEN 1.95 WHEN 'USD' THEN 1.52 WHEN 'EUR' THEN 1.66 END AS DECIMAL(18,2)) AS gross_pay_aud,
  e.department_name,
  e.business_unit,
  e.country,
  e.region
FROM harbourstone.bronze_payroll p
JOIN harbourstone.silver_employees e ON e.employee_id = p.employee_id;

-- silver_leave_requests: Leave requests with department, region and month.

DROP TABLE IF EXISTS harbourstone.silver_leave_requests;

CREATE TABLE harbourstone.silver_leave_requests
AS
SELECT
  l.leave_id,
  l.employee_id,
  l.leave_type,
  l.start_date,
  l.end_date,
  CAST(DATE_TRUNC('month', l.start_date) AS DATE) AS leave_month,
  l.days_taken,
  l.leave_status,
  l.reason,
  e.department_name,
  e.business_unit,
  e.country,
  e.region
FROM harbourstone.bronze_leave_requests l
JOIN harbourstone.silver_employees e ON e.employee_id = l.employee_id;

-- silver_performance_reviews: Performance reviews with employee and reviewer
-- names.

DROP TABLE IF EXISTS harbourstone.silver_performance_reviews;

CREATE TABLE harbourstone.silver_performance_reviews
AS
SELECT
  v.review_id,
  v.employee_id,
  e.first_name || ' ' || e.last_name AS employee_name,
  v.reviewer_id,
  m.first_name || ' ' || m.last_name AS reviewer_name,
  v.review_period,
  v.rating,
  v.review_text,
  e.department_name,
  e.business_unit,
  e.country,
  e.region
FROM harbourstone.bronze_performance_reviews v
JOIN harbourstone.silver_employees e ON e.employee_id = v.employee_id
LEFT JOIN harbourstone.silver_employees m ON m.employee_id = v.reviewer_id;

-- ----------------------------------------------------------------------------
-- Gold: business-ready data products for reporting and AI. Built from silver.
-- ----------------------------------------------------------------------------

-- gold_headcount: Active headcount, tenure, hires, leavers and attrition by
-- department and region.

DROP TABLE IF EXISTS harbourstone.gold_headcount;

CREATE TABLE harbourstone.gold_headcount
AS
SELECT
  business_unit,
  department_name,
  region,
  country,
  SUM(CASE WHEN is_active THEN 1 ELSE 0 END) AS active_headcount,
  ROUND(AVG(CASE WHEN is_active THEN tenure_years END), 1) AS avg_tenure_years,
  SUM(CASE WHEN hire_date >= CAST(DATEADD(day, -365, CURRENT_DATE) AS DATE) THEN 1 ELSE 0 END) AS hires_last_12_months,
  SUM(CASE WHEN termination_date >= CAST(DATEADD(day, -365, CURRENT_DATE) AS DATE) THEN 1 ELSE 0 END) AS leavers_last_12_months,
  ROUND(CAST(SUM(CASE WHEN termination_date >= CAST(DATEADD(day, -365, CURRENT_DATE) AS DATE) THEN 1 ELSE 0 END) AS DECIMAL(18,4)) * 100 / NULLIF(SUM(CASE WHEN is_active THEN 1 ELSE 0 END), 0), 1) AS attrition_rate_pct
FROM harbourstone.silver_employees
GROUP BY 1, 2, 3, 4;

-- gold_pay_equity: Current salaries (AUD) by grade, business unit, gender and
-- region, for pay equity analysis.

DROP TABLE IF EXISTS harbourstone.gold_pay_equity;

CREATE TABLE harbourstone.gold_pay_equity
AS
SELECT
  pay_grade,
  business_unit,
  gender,
  region,
  COUNT(*) AS employees,
  CAST(AVG(base_salary_aud) AS DECIMAL(18,2)) AS avg_base_salary_aud,
  MIN(base_salary_aud) AS min_base_salary_aud,
  MAX(base_salary_aud) AS max_base_salary_aud
FROM harbourstone.silver_compensation
WHERE is_current AND is_active
GROUP BY 1, 2, 3, 4;

-- gold_leave_summary: Leave requests and approved days by month, type,
-- business unit and region.

DROP TABLE IF EXISTS harbourstone.gold_leave_summary;

CREATE TABLE harbourstone.gold_leave_summary
AS
SELECT
  leave_month,
  leave_type,
  business_unit,
  region,
  COUNT(*) AS requests,
  SUM(CASE WHEN leave_status = 'APPROVED' THEN days_taken ELSE 0 END) AS approved_days,
  SUM(CASE WHEN leave_status = 'PENDING' THEN 1 ELSE 0 END) AS pending_requests
FROM harbourstone.silver_leave_requests
GROUP BY 1, 2, 3, 4;

-- gold_performance_summary: Review ratings by department and region: averages
-- and high and low performers.

DROP TABLE IF EXISTS harbourstone.gold_performance_summary;

CREATE TABLE harbourstone.gold_performance_summary
AS
SELECT
  review_period,
  business_unit,
  department_name,
  region,
  COUNT(*) AS reviews,
  ROUND(AVG(CAST(rating AS DECIMAL(4,2))), 2) AS avg_rating,
  SUM(CASE WHEN rating >= 4 THEN 1 ELSE 0 END) AS high_performers,
  SUM(CASE WHEN rating <= 2 THEN 1 ELSE 0 END) AS low_performers
FROM harbourstone.silver_performance_reviews
GROUP BY 1, 2, 3, 4;
